            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xB8F4256E1AD8F820ULL) + aOUSaltF[((aIndex + 289U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x94B6DA5F7BA7606EULL;
            aOrbiterC = RotL64((aOrbiterC * 0x17EE63AA9F268737ULL), 19U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0x92F83E23E92977A5ULL) + aOUSaltD[(((511U - aIndex) + 147U)) & S_SALT1];
