            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterJ = ((aWandererK + RotL64(aIngress, 51U)) + RotL64(aCarry, 3U)) + 0x8204461B7C4C36C3ULL;
            aOrbiterC = ((aWandererE + RotL64(aScatter, 23U)) + RotL64(aCarry, 51U)) + 0x8E3B25ED10B3EBDDULL;
            aOrbiterI = ((aWandererG + RotL64(aCross, 41U)) + 0x43DFB04E65898CF0ULL) + aOASaltD[((aIndex + 40U)) & S_SALT1];
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 27U)) + 0x53D0364DC3DB2D59ULL) + aOASaltG[(((511U - aIndex) + 431U)) & S_SALT1];
            aOrbiterE = (aWandererI + RotL64(aIngress, 19U)) + 0x11E55B04B2B20728ULL;
            aOrbiterF = (aWandererH + RotL64(aPrevious, 35U)) + 0xDBDF5D61609420F1ULL;
