            aOrbiterC = RotL64((aOrbiterC * 0x4F4CA7766A35D379ULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0xD55ED8F6FAB0A02DULL) + aOUSaltC[(((511U - aIndex) + 235U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x7922A07C6E992885ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xEA1CD6D3112EB92DULL), 51U);
