            aWandererH = aWandererH ^ ((RotL64(aIngress, 29U) + aOrbiterJ) + RotL64(aOrbiterE, 5U));
            aWandererD = aWandererD + (((RotL64(aScatter, 23U) + RotL64(aOrbiterB, 39U)) + aOrbiterD) + RotL64(aCarry, 11U));
            //
            aCarry = aCarry + (RotL64(aWandererH, 21U) ^ aWandererE);
            aCarry = aCarry + (RotL64(aWandererA, 27U) ^ aWandererC);
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererD, 14U));
