            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 13U) ^ RotL64(aCarry, 47U)) + (RotL64(aCross, 35U) + RotL64(aIngress, 60U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (aWandererH + RotL64(aPrevious, 11U)) + 0xD0D4FD33BB4EC1F0ULL;
            aOrbiterF = ((aWandererB + RotL64(aScatter, 41U)) + RotL64(aCarry, 23U)) + 0x4F4FB97935338E4DULL;
            aOrbiterJ = ((aWandererF + RotL64(aIngress, 4U)) + 0xA1183B6842899D1CULL) + aOASaltC[((aIndex + 218U)) & S_SALT1];
            aOrbiterE = (aWandererI + RotL64(aCross, 21U)) + 0x812F5783A83256D2ULL;
            aOrbiterH = ((aWandererC + RotL64(aPrevious, 53U)) + 0xA9B82752EB57A99EULL) + aOASaltB[(((511U - aIndex) + 495U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aCross, 27U)) + RotL64(aCarry, 37U)) + 0x732908B2BE30412EULL;
            aOrbiterI = (((aWandererJ + RotL64(aIngress, 47U)) + RotL64(aCarry, 11U)) + 0x25D3E8F640850E05ULL) + aOASaltA[(((511U - aIndex) + 387U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x0574855F6EED6665ULL;
