            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x434C5D3A06C1653CULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterC) ^ 0xFA7734504EDAF85DULL) ^ aOUSaltG[((aIndex + 85U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xAF9DAF1E8709F3EDULL), 13U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0xE450BAE7EB25CF33ULL) + aOUSaltE[((aIndex + 248U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xD2188DAA702778B8ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x93B09F3D3B40702FULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xC9235E5BADC3F334ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x17BF9CE966375511ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x60D26FBDC6055F8FULL), 19U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterF, 51U);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterI, 5U));
            aIngress = aIngress + (RotL64(aOrbiterH, 36U) ^ aOrbiterG);
            aIngress = aIngress + RotL64(aOrbiterE, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aCross, 29U) + aOrbiterG) + RotL64(aOrbiterJ, 29U));
            aWandererF = aWandererF + (((RotL64(aScatter, 37U) + RotL64(aOrbiterC, 5U)) + aOrbiterH) + RotL64(aCarry, 53U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 47U) + RotL64(aOrbiterG, 13U)) + aOrbiterE);
            aWandererI = aWandererI + ((RotL64(aPrevious, 11U) + RotL64(aOrbiterH, 60U)) + aOrbiterJ);
            aWandererC = aWandererC ^ (((RotL64(aScatter, 60U) + aOrbiterH) + RotL64(aOrbiterI, 53U)) + aWUSaltA[(((511U - aIndex) + 300U)) & S_SALT1]);
            aWandererK = aWandererK + ((((RotL64(aCross, 3U) + RotL64(aOrbiterG, 35U)) + aOrbiterF) + RotL64(aCarry, 5U)) + aWUSaltG[(((511U - aIndex) + 295U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 19U) + aOrbiterF) + RotL64(aOrbiterH, 19U)) + aWUSaltD[((aIndex + 28U)) & S_SALT1]);
