            aCross ^= (RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 15669U)) & S_BLOCK1], 51U) ^ RotL64(aMagmaLaneA[((aIndex + 15302U)) & S_BLOCK1], 37U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 3U) ^ RotL64(aIngress, 36U)) + (RotL64(aPrevious, 51U) ^ RotL64(aCross, 19U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = (((aWandererF + RotL64(aPrevious, 21U)) + RotL64(aCarry, 5U)) + 0xDAC741B54F0363F5ULL) + aOASaltH[(((511U - aIndex) + 211U)) & S_SALT1];
            aOrbiterI = (((aWandererH + RotL64(aCross, 51U)) + RotL64(aCarry, 27U)) + 0xAF5D8A70B36238B0ULL) + aOASaltA[((aIndex + 35U)) & S_SALT1];
            aOrbiterK = ((aWandererC + RotL64(aScatter, 37U)) + RotL64(aCarry, 51U)) + 0xDF056B92829F25EEULL;
            aOrbiterF = ((aWandererJ + RotL64(aIngress, 3U)) + 0x14D05BAF75904516ULL) + aOASaltF[((aIndex + 129U)) & S_SALT1];
            aOrbiterA = (aWandererD + RotL64(aScatter, 43U)) + 0x12E9E3655A7C3D62ULL;
            aOrbiterB = ((aWandererA + RotL64(aPrevious, 30U)) + 0xEA58883DD77C978CULL) + aOASaltC[(((511U - aIndex) + 485U)) & S_SALT1];
            aOrbiterD = ((aWandererI + RotL64(aIngress, 57U)) + 0x8EB79386C42FAB36ULL) + aOASaltB[(((511U - aIndex) + 24U)) & S_SALT1];
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x2CF5411DB5718177ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x69350EB9EF887457ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x4B5629E1AB177F7FULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xCDEE70C5467E4EC5ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x456639B06D828F07ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF2590F0EDBC10B49ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x55E0A14ADCF477EAULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0x91E4F66772A647F3ULL) ^ aOUSaltF[(((511U - aIndex) + 118U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xA8A2BADF4891C3D7ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x23B58E94434EE2FDULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xA0639AF184CF1277ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xFC360514851345D9ULL), 3U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0xF80C5019814AF178ULL) + aOUSaltE[(((511U - aIndex) + 431U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0xE0AECD06CA67C53BULL) ^ aOUSaltD[((aIndex + 322U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xC7E5DA3ACF8A7EF3ULL), 51U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xC9C743C57B0F5737ULL) + aOUSaltH[(((511U - aIndex) + 391U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x7D3BF8B82DDDA862ULL) ^ aOUSaltC[((aIndex + 264U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x4E9EF7F3BF3EEDB1ULL), 11U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x4F421D72D7A3E7D6ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0xBB8A57AC6C1F617BULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF5CE5F36266EB20BULL), 19U);
            //
            aIngress = RotL64(aOrbiterK, 11U) ^ aOrbiterJ;
            aIngress = aIngress + (RotL64(aOrbiterD, 5U) ^ aOrbiterA);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterI, 41U));
            aIngress = aIngress + RotL64(aOrbiterB, 35U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA + ((((RotL64(aIngress, 13U) + RotL64(aOrbiterD, 23U)) + aOrbiterJ) + RotL64(aCarry, 35U)) + aWUSaltE[(((511U - aIndex) + 20U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 5U) + aOrbiterD) + RotL64(aOrbiterI, 11U));
            aWandererC = aWandererC + (((RotL64(aCross, 26U) + RotL64(aOrbiterF, 5U)) + aOrbiterB) + aWUSaltC[((aIndex + 405U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aScatter, 37U) + aOrbiterD) + RotL64(aOrbiterB, 41U)) + aWUSaltB[(((511U - aIndex) + 17U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aIngress, 47U) + RotL64(aOrbiterA, 51U)) + aOrbiterB);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 53U) + RotL64(aOrbiterF, 30U)) + aOrbiterA);
            aWandererF = aWandererF + ((((RotL64(aPrevious, 19U) + RotL64(aOrbiterK, 57U)) + aOrbiterJ) + RotL64(aCarry, 51U)) + aWUSaltA[((aIndex + 511U)) & S_SALT1]);
