            aOrbiterB = ((aWandererG + RotL64(aCross, 57U)) + RotL64(aCarry, 21U)) + 0x0C597D95ECEA5D5BULL;
            aOrbiterG = ((aWandererJ + RotL64(aPrevious, 43U)) + 0x96B6BA8E407AAB26ULL) + aOASaltA[((aIndex + 466U)) & S_SALT1];
