            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xE0810D368C4FDA28ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0x0DD8F7E8E513C55FULL) ^ aOUSaltB[(((511U - aIndex) + 321U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x8D8DB914994320A7ULL), 57U);
